SELECT business_id, name, address, city, state, postal_code, stars, categories
FROM business
WHERE city = 'Tucson' AND categories LIKE '%Cafes%';

SELECT photo_id, business_id, caption, label
FROM photo
WHERE photo_id IN (?,?,...);

SELECT p.business_id, p.photo_id, p.label
FROM photo p
WHERE p.label IN ('outside');

ATTACH DATABASE 'D:/Yelp-JSON/db/sqlite3/business.db' AS business_db;
SELECT r.review_id, r.business_id, r.stars, r.text, r.date,
       b.name AS business_name, b.address, b.city, b.state, b.postal_code
FROM review r
JOIN business_db.business b ON b.business_id = r.business_id
WHERE r.user_id = '<randy_user_id>' AND b.city = 'Tampa';

SELECT photo_id, business_id, label
FROM photo_db.photo
WHERE business_id IN (?,?,...);

